\documentclass[conference]{IEEEtran}
\title{A Low-Power Sensor Node for Urban Air Quality Monitoring}
\author{
\IEEEauthorblockN{Alice Chen}
\IEEEauthorblockA{Department of Electrical Engineering\\
Tsinghua University\\
Beijing, China\\
alice.chen@example.edu}
\and
\IEEEauthorblockN{Bob Wang}
\IEEEauthorblockA{School of Automation\\
Beihang University\\
Beijing, China\\
bob.wang@example.edu}
\begin{document}
\maketitle
\begin{abstract}
This paper presents a low-power sensor node for urban air quality
monitoring and reports a three-month deployment on twelve street
lamps.
\end{abstract}
\begin{IEEEkeywords}
sensor networks, air quality, low power
\end{IEEEkeywords}

\section{Introduction}
Urban air pollution varies at the scale of individual streets, yet
reference monitors are sparse. A dense network of inexpensive nodes can
fill the gap, provided each node survives a full season without mains
power.

\section{Hardware}
The node samples a particulate sensor and a gas sensor once per minute
and sleeps between samples. The average power draw is
\begin{equation}
P_{\mathrm{avg}} = \frac{t_{\mathrm{on}} P_{\mathrm{on}} + t_{\mathrm{sleep}} P_{\mathrm{sleep}}}{t_{\mathrm{on}} + t_{\mathrm{sleep}}},
\end{equation}
which the firmware keeps below 9~mW so that a 20~Ah battery lasts a
full season.

\section{Deployment}
Twelve nodes ran on street lamps from March to May. Data return was
above 94\% for ten of the twelve nodes; the two outliers suffered
water ingress after a storm.

\section{Conclusion}
A sub-10~mW power budget is achievable without sacrificing sampling
density, and street-lamp mounting gives adequate coverage for a pilot
network.
\end{document}

